def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for i in range(n):
        pair = history[i]
        if pair[1] == 'C':
            opp_c += 1
        if pair[0] == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    # Count mutual defections and delayed responses to our previous defection.
    both_d = 0
    for i in range(n):
        pair = history[i]
        if pair[0] == 'D' and pair[1] == 'D':
            both_d += 1

    d_to_d = 0
    d_to_c = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'D':
                d_to_d += 1
            else:
                d_to_c += 1

    # Current opponent defection streak.
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    # Opponent defections in the last 5 executed rounds.
    start = n - 5
    if start < 0:
        start = 0
    recent5_opp_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent5_opp_d += 1

    opp_rate = (opp_c + 1.0) / (n + 2.0)

    # Defensively punish clearly noncooperative opponents or hard defection runs.
    if opp_rate < 0.35 or streak_d >= 3:
        return 'D'

    # A single early calibration defection, used only against partners that look cooperative.
    if n == 5 and my_d == 0:
        return 'D'

    # After the calibration move, hold fire for one round to see whether the partner punishes.
    if n == 6 and my_last == 'D' and opp_d <= 2:
        return 'C'

    # If the partner has never defected, exploit them for the remainder of the match.
    if opp_d == 0 and my_d >= 1:
        return 'D'

    if opp_last == 'D':
        # If their defection looks like a response to one of our recent defections,
        # forgive an isolated punishment to restore cooperation when appropriate.
        provoked = False
        if n >= 2 and history[-2][0] == 'D':
            provoked = True
        if n >= 3 and history[-3][0] == 'D':
            provoked = True

        if provoked:
            if opp_rate >= 0.60 and streak_d == 1:
                return 'C'
            return 'D'

        # Unprovoked defection: give a short punishment.
        return 'D'

    # Opponent just cooperated. If evidence says they do not punish our defections,
    # and there is no history of simultaneous mutual defection, shift to exploitation.
    if (both_d == 0 and d_to_d == 0 and d_to_c >= 1 and
            opp_rate >= 0.65 and recent5_opp_d == 0):
        return 'D'

    # Otherwise, if we were the last defector and they forgave, repair the relationship.
    if my_last == 'D':
        return 'C'

    # Default to maintaining mutual cooperation.
    return 'C'
